css:
.btn-game {
  padding: 16px 32px;
  font-family: "Arial Black", Gadget, sans-serif;
  font-size: 20px;
  text-transform: uppercase;
  letter-spacing: 1px;

  background: #333;
  color: #eee;

  border: none;
  border-radius: 4px;
  cursor: pointer;
  position: relative;

  box-shadow:
    0 8px 0 #1a1a1a,
    0 15px 20px rgba(0, 0, 0, 0.5);

  transition: all 0.1s ease;
  outline: none;
}

.btn-game:hover {
  background: #3a3a3a;
  transform: translateY(-2px);
  box-shadow:
    0 10px 0 #1a1a1a,
    0 18px 25px rgba(0, 0, 0, 0.6);
}

.btn-game:active {
  background: #222;
  transform: translateY(6px);
  box-shadow:
    0 2px 0 #1a1a1a,
    0 5px 10px rgba(0, 0, 0, 0.4);
}

.btn-game::after {
  content: "";
  position: absolute;
  top: 8px;
  right: 8px;
  width: 6px;
  height: 6px;
  background: #ff3333;
  border-radius: 50%;
  box-shadow: 0 0 5px #ff0000;
}
